'Bi':xx(O=.1,Cu=.3,Sr=.2,Ca=.2,Bi=.2),
'hist':xx(O=.52381,Cu=.11,Ba=.114667,Sr=.117647,Ca=.046333),
'YBCO':xx(O=.538462,Cu=.230769,Ba=.153846,Y=.076923),
}
models2={k:m for k,m in models.items() if k not in ['ridge','knn']}
models2['cat']=CatBoostRegressor(iterations=800,depth=6,learning_rate=.03,l2_leaf_reg=10,verbose=False,random_seed=1)
print('candidate sum '+ ' '.join(models2))
for m in models2.values():m.fit(X,D.target)
for k,x in cands.items():print(k,round(x.sum(),3),*[round(m.predict(x.reshape(1,-1))[0],1) for m in models2.values()])
