cat > /tmp/ensopt.py <<'PY'
exec(open('/tmp/model.py').read().split('kf=')[0])
from catboost import CatBoostRegressor
import warnings;warnings.filterwarnings('ignore')
bs=np.array([.697674,.454545,.333333,.285714,.4,.272727,.78,.521978,.502513,.98,.972,.265043,.5,1,.5,.28,1,.9918,1,.6])
ms=[models['rf'],models['rf1'],models['et'],models['et1'],models['gbr'],models['hist'],CatBoostRegressor(iterations=800,depth=6,learning_rate=.03,l2_leaf_reg=10,verbose=False,random_seed=1)]
for m in ms:m.fit(X,D.target)
def pred(c):return np.mean([m.predict(c) for m in ms],axis=0)
rng=np.random.default_rng(5);C=[]
for a,b in [(.1,1),(.2,1),(.4,1),(.5,2),(1,1),(2,5)]:C.append(rng.beta(a,b,(100000,20))*bs)
C=np.vstack(C);p=pred(C);starts=C[np.argpartition(p,-200)[-200:]]
grids=[]
for j,e in enumerate(els):
 v=np.unique(np.r_[0,bs[j],X[e][X[e]<=bs[j]]]);grids.append(np.unique(np.r_[v,(v[1:]+v[:-1])/2]))
for rnd in range(5):
 for j,g in enumerate(grids):
  cc=np.repeat(starts,len(g),0);cc[:,j]=np.tile(g,len(starts));pp=pred(cc).reshape(len(starts),len(g));starts[:,j]=g[pp.argmax(1)]
p=pred(starts)
for ii in np.argsort(p)[-10:][::-1]:
 x=starts[ii];print('pred',p[ii],'sum',x.sum(),'individual',[round(m.predict(x.reshape(1,-1))[0],1) for m in ms]);print(' '.join(f'{e}={v:.6f}' for e,v in zip(els,x)))
